@Component("experiment-entity-projector")
public class ExperimentEntityProjector implements EntityProjector<Experiment>{
		
	// core constructor
	public ExperimentEntityProjector(ProjectorRegistry registry,
										ExperimentRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Experiment> getEntityClass() {
		return Experiment.class;
	}

    /*
	 * Insert a Experiment
	 * 
     * @param	entity Experiment
     */
    public Experiment create( Experiment entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Experiment
	 * 
     * @param	entity Experiment
     */
    public Experiment update( Experiment entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Experiment
	 * 
     * @param	id		UUID
     */
    public Experiment delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Experiment entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Campaign
     * 
     * @param	parentId	UUID
     * @param	assignment 	Campaign 
     * @return	Experiment
     */
    public Experiment assignCampaign( UUID parentId, Campaign assignment ) {
	    LOGGER.info("assigning Campaign as " + assignment.toString() );

	    Experiment parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Campaign.class, assignment.getCampaignId());

	    // ------------------------------------------
		// assign the Campaign to the parent entity
		// ------------------------------------------ 
	    parentEntity.setCampaign( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Campaign
	 * 
	 * @param	parentId		UUID
	 * @return	Experiment
	 */
	public Experiment unAssignCampaign( UUID parentId ) {
		Experiment parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Campaign on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Campaign on the parent entithy
		// ------------------------------------------     
	    parentEntity.setCampaign(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the Variants
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Experiment
     */
    public Experiment addToVariants( UUID parentId, ExperimentVariant addTo ) {
	    LOGGER.info("handling AssignVariantsToExperimentEvent - " );
	    
	    Experiment parentEntity = repository.findById(parentId).get();
	    ExperimentVariant child = registry.project( ExperimentVariant.class, addTo.getExperimentVariantId());
	    
	    parentEntity.getVariants().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Variants
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Experiment
     */
	public Experiment removeFromVariants( UUID parentId, ExperimentVariant removeFrom ) {
	    LOGGER.info("handling RemoveVariantsFromExperimentEvent " );
	
	    Experiment parentEntity = repository.findById(parentId).get();
	    ExperimentVariant child = registry.project( ExperimentVariant.class, removeFrom.getExperimentVariantId());
	    
	    parentEntity.getVariants().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Experiment via an FindExperimentQuery
     * @return 	query	FindExperimentQuery
     */
    @SuppressWarnings("unused")
    public Experiment find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Experiment - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Experiments
     *
     * @param	query	FindAllExperimentQuery 
     * @return 	List<Experiment> 
     */
    @SuppressWarnings("unused")
    public List<Experiment> findAll( FindAllExperimentQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Experiment - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final ExperimentRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(ExperimentEntityProjector.class.getName());

}
